import java.util.Arrays;

public class CoinChange{

    static int count(int[] coins, int sum) {
        int n = coins.length;

        int[][] dp = new int[n + 1][sum + 1];

        dp[0][0] = 1;
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= sum; j++) {

                dp[i][j] += dp[i - 1][j];

                if (j - coins[i - 1] >= 0) {

                    dp[i][j] += dp[i][j - coins[i - 1]];
                }
            }
        }
        return dp[n][sum];
}
    public static void main(String[] args) {
        int[] coins = {1, 2, 3};
        int sum = 5;
        System.out.println(count(coins, sum));
    }
}

public final class CoinChange {

    private CoinChange() {
    }

    static int count(int[] coins, int targetSum) {
        int[] waysBySum = new int[targetSum + 1];
        waysBySum[0] = 1;

        for (int coin : coins) {
            for (int currentSum = coin; currentSum <= targetSum; currentSum++) {
                waysBySum[currentSum] += waysBySum[currentSum - coin];
            }
        }

        return waysBySum[targetSum];
    }

    public static void main(String[] args) {
        int[] coins = {1, 2, 3};
        int targetSum = 5;
        System.out.println(count(coins, targetSum));
    }
}

